public struct Crm: Codable, Sendable, Equatable {
    public var stages: [String: Stage]
    public var deals: [String: Deal]
    public var contacts: [String: Contact]
    public var activities: [String: Activity]
    public var notes: [String: Note]
    public var automations: [String: Automation]
    /// Record id → when it was created, written once with the record by the
    /// account that created it. That owner stamp IS the record's `created_by`:
    /// no node accepts a rewrite of it, so neither can anyone take over a
    /// record's authorship by writing a field.
    public var createdBy: [String: UInt64]
    public var currency: String
    public var rottingDays: UInt32

    public init(stages: [String: Stage], deals: [String: Deal], contacts: [String: Contact], activities: [String: Activity], notes: [String: Note], automations: [String: Automation], createdBy: [String: UInt64], currency: String, rottingDays: UInt32) {
        self.stages = stages
        self.deals = deals
        self.contacts = contacts
        self.activities = activities
        self.notes = notes
        self.automations = automations
        self.createdBy = createdBy
        self.currency = currency
        self.rottingDays = rottingDays
    }

    enum CodingKeys: String, CodingKey {
        case stages
        case deals
        case contacts
        case activities
        case notes
        case automations
        case createdBy = "created_by"
        case currency
        case rottingDays = "rotting_days"
    }
}

/// A deal: an opportunity with a value, moving through the stages.
///
/// Indexed by the fields the board filters on, so a stage column, an owner's
/// deals or a person's deals is a seek rather than a scan of every deal.
public struct Deal: Codable, Sendable, Equatable {
    public var id: String
    public var title: String
    public var value: UInt64
    public var organization: String
    public var contactId: String
    public var owner: String
    public var stageId: String
    public var status: String
    public var lostReason: String
    /// Expected close date, ms since the epoch.
    public var expectedClose: UInt64
    /// Where the deal came from (referral, inbound, outbound, event, …).
    public var source: String
    /// When the deal entered its current stage — what "rotting" measures.
    public var stageEnteredAt: UInt64
    public var closedAt: UInt64
    public var createdAt: UInt64

    public init(id: String, title: String, value: UInt64, organization: String, contactId: String, owner: String, stageId: String, status: String, lostReason: String, expectedClose: UInt64, source: String, stageEnteredAt: UInt64, closedAt: UInt64, createdAt: UInt64) {
        self.id = id
        self.title = title
        self.value = value
        self.organization = organization
        self.contactId = contactId
        self.owner = owner
        self.stageId = stageId
        self.status = status
        self.lostReason = lostReason
        self.expectedClose = expectedClose
        self.source = source
        self.stageEnteredAt = stageEnteredAt
        self.closedAt = closedAt
        self.createdAt = createdAt
    }

    enum CodingKeys: String, CodingKey {
        case id
        case title
        case value
        case organization
        case contactId = "contact_id"
        case owner
        case stageId = "stage_id"
        case status
        case lostReason = "lost_reason"
        case expectedClose = "expected_close"
        case source
        case stageEnteredAt = "stage_entered_at"
        case closedAt = "closed_at"
        case createdAt = "created_at"
    }
}

